() => {
  const btn = [...document.querySelectorAll('button')].find(b => b.textContent.trim() === '退出全屏');
  if (!btn) return { error: 'no exit-fullscreen button' };
  const panel = btn.closest('section, div');
  // climb to the element that is fixed/covering
  let el = btn;
  let target = null;
  while (el && el !== document.body) {
    const cs = getComputedStyle(el);
    if (cs.position === 'fixed' || cs.position === 'absolute') {
      const r = el.getBoundingClientRect();
      if (r.width >= window.innerWidth - 4 && r.height >= window.innerHeight - 4) { target = el; break; }
    }
    el = el.parentElement;
  }
  if (!target) return { error: 'no fullscreen covering element found', btnParentTag: btn.parentElement.tagName, btnParentClass: btn.parentElement.className };
  const r = target.getBoundingClientRect();
  const cs = getComputedStyle(target);
  // check whether left field sidebar is covered: pick a point at left 100px, middle height and elementFromPoint
  const probe = document.elementFromPoint(100, window.innerHeight / 2);
  const probeInfo = probe ? { tag: probe.tagName, cls: String(probe.className).slice(0, 80), text: (probe.textContent || '').slice(0, 40) } : null;
  const insideTarget = probe ? target.contains(probe) : false;
  return {
    viewport: { w: window.innerWidth, h: window.innerHeight },
    rect: { x: r.x, y: r.y, w: r.width, h: r.height },
    position: cs.position, zIndex: cs.zIndex, overflow: cs.overflowY,
    coversSidebar: insideTarget,
    probeInfo
  };
}

() => {
  const btns = [...document.querySelectorAll('button')].filter(b => b.textContent.trim() === '退出全屏');
  if (btns.length !== 1) return { error: 'unexpected exit-fullscreen count', count: btns.length };
  const btn = btns[0];
  let el = btn, target = null;
  while (el && el !== document.body) {
    const cs = getComputedStyle(el);
    if (cs.position === 'fixed') {
      const r = el.getBoundingClientRect();
      if (r.width >= window.innerWidth - 4 && r.height >= window.innerHeight - 4) { target = el; break; }
    }
    el = el.parentElement;
  }
  if (!target) return { error: 'no fixed overlay' };
  const r = target.getBoundingClientRect();
  const canvas = target.querySelector('canvas');
  const chartRect = canvas ? canvas.getBoundingClientRect() : null;
  const probe = document.elementFromPoint(80, 200);
  return {
    viewport: { w: window.innerWidth, h: window.innerHeight },
    overlay: { x: r.x, y: r.y, w: r.width, h: r.height },
    coversAll: r.x <= 1 && r.y <= 1 && r.width >= window.innerWidth - 2 && r.height >= window.innerHeight - 2,
    probeInside: probe ? target.contains(probe) : false,
    chartHeight: chartRect ? Math.round(chartRect.height) : null,
    overflow: getComputedStyle(target).overflowY
  };
}

() => {
  const btn = [...document.querySelectorAll('button')].find(b => b.textContent.trim() === '退出全屏');
  let el = btn, target = null;
  while (el && el !== document.body) {
    const cs = getComputedStyle(el);
    if (cs.position === 'fixed') {
      const r = el.getBoundingClientRect();
      if (r.width >= window.innerWidth - 4) { target = el; break; }
    }
    el = el.parentElement;
  }
  const canvases = [...document.querySelectorAll('canvas')].map(c => ({ w: c.width, h: c.height, rectH: Math.round(c.getBoundingClientRect().height), inOverlay: target.contains(c) }));
  const svgs = [...target.querySelectorAll('svg')].slice(0, 5).map(s => Math.round(s.getBoundingClientRect().height));
  // find the echarts container div (usually has _echarts_instance_ attribute)
  const echartsDiv = [...target.querySelectorAll('div')].find(d => [...d.attributes].some(a => a.name.startsWith('_echarts_instance_')));
  const eh = echartsDiv ? Math.round(echartsDiv.getBoundingClientRect().height) : null;
  return { canvases, svgHeights: svgs, echartsDivHeight: eh };
}

