      if (r.width >= window.innerWidth - 4) { target = el; break; }
    }
    el = el.parentElement;
  }
  const app = target.querySelector('[role="application"], [role="img"], canvas, .recharts-wrapper, .recharts-surface');
  const info = app ? { tag: app.tagName, role: app.getAttribute('role'), h: Math.round(app.getBoundingClientRect().height), cls: String(app.className).slice(0, 60) } : null;
  const svgsAll = [...target.querySelectorAll('svg')].map(s => ({ w: Math.round(s.getBoundingClientRect().width), h: Math.round(s.getBoundingClientRect().height), cls: String(s.className.baseVal || s.className).slice(0, 50) }));
  return { app: info, svgCount: svgsAll.length, bigSvgs: svgsAll.filter(s => s.h > 100) };
}

() => {
  const w = document.querySelector('.recharts-wrapper');
  const fixedOverlays = [...document.querySelectorAll('div')].filter(d => getComputedStyle(d).position === 'fixed' && d.getBoundingClientRect().width >= window.innerWidth - 4);
  return {
    normalChartHeight: w ? Math.round(w.getBoundingClientRect().height) : null,
    remainingFullscreenOverlays: fixedOverlays.length,
    exitButtons: [...document.querySelectorAll('button')].filter(b => b.textContent.trim() === '退出全屏').length
  };
}
